import pandas as pd
import glob
files = glob.glob('/workspace/CHIP_DP10_GQ20_PASS/*.xlsx')
found = False
for f in files[:5]:
    df = pd.read_excel(f, header=1)
    if 'Gene Names' in df.columns:
        for i, row in df.iterrows():
            if 'MMACHC' in str(row['Gene Names']):
                print(row[['Gene Names', 'In_CHIP', 'Sequence Ontology (Combined)']])
                found = True
                break
    if found:
        break
